const C = {
  paper: 0xd8c9a3,
  blueDk: 0x1b3a5c,  // deep Prussian (wave body)
  blueMd: 0x2e5f8a,
  blueLt: 0x7fa8c9,  // light blue band
  white: 0xffffff,   // foam (bright white to read against paper)
  fuji:  0x27476e,
  snow:  0xf2ede1,
  hull:  0xd9a86a,
  hullDk:0x8a5a2b,
  mat:   0xe8e0cc,
  fig:   0x3a2a1a,
};

const scene = new THREE.Scene();
scene.background = new THREE.Color(C.paper);
scene.fog = new THREE.Fog(C.paper, 70, 180);

const camera = new THREE.PerspectiveCamera(40, innerWidth/innerHeight, 0.1, 400);
camera.position.set(0, 7, 50);
camera.lookAt(0, 3, 0);

const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setSize(innerWidth, innerHeight);
renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
document.body.appendChild(renderer.domElement);

scene.add(new THREE.HemisphereLight(0xf5ecd8, 0x2e5f8a, 1.15));
const sun = new THREE.DirectionalLight(0xfff4dd, 0.85);
sun.position.set(-8, 20, 10);
scene.add(sun);

const mat = (c, o={}) => new THREE.MeshLambertMaterial({ color: c, flatShading: true, ...o });

